import React from 'react';
import { MultiSelect } from 'carbon-components-react';

function App() {
  const items = [
    { id: 'item-1', text: 'An example option that is really long' },
    { id: 'item-2', text: 'Option 1' },
    { id: 'item-3', text: 'Option 2' },
    { id: 'item-4', text: 'Option 3' },
    { id: 'item-5', text: 'Option 4' },
    { id: 'item-6', text: 'Option 5' },
  ];

  const initialSelectedItems = [
    { id: 'item-1', text: 'An example option that is really long' },
    { id: 'item-2', text: 'Option 1' },
  ];

  return (
    <div style={{ padding: '2rem' }}>
      <MultiSelect
        label="Multiselect title"
        items={items}
        itemToString={(item) => (item ? item.text : '')}
        initialSelectedItems={initialSelectedItems}
        filterable
      />
    </div>
  );
}

export default App;
